    if token: [REDACTED_SECRET]'Authorization']='Bearer '+token
    req=urllib.request.Request(BASE+path,data=body,headers=headers,method=method)
    try:
        with urllib.request.urlopen(req,timeout=20) as resp:
            return resp.status, resp.read()
    except urllib.error.HTTPError as e:
        payload=e.read()
        if e.code==429:
            wait=float(e.headers.get('Retry-After','1'))
            time.sleep(wait)
            return request(path,method,data,token,retry_auth)
        if e.code==401 and retry_auth:
            TOKEN=[REDACTED_SECRET]
            return request(path,method,data,TOKEN,False)
        return e.code,payload

def fetch_token():
    st,b=request('/token','POST',{})
    if st"'!=200: raise RuntimeError(('"'token',st,b))
    return json.loads(b)['token']

TOKEN=[REDACTED_SECRET]
# Discover page count and collect every page, retrying any transient HTTP/server failure.
orders=[]; total_pages=None; page=1; occurrences={}; duplicate_listings=0
while total_pages is None or page<=total_pages:
    attempts=0
    while True:
        st,b=request(f'/orders?page={page}',token=TOKEN)
        if st==200: break
        attempts+=1
        if attempts>=8: raise RuntimeError((page,st,b))
        time.sleep(min(2**attempts,20))
    obj=json.loads(b)
    total_pages=obj['total_pages']
    for o in obj['items']:
        oid=o['id']
        if oid in occurrences: duplicate_listings+=1
        else: occurrences[oid]=o
    page+=1

start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
customers={}
by_region={'north':0,'south':0,'east':0,'west':0}
qualifying=[]
for o in occurrences.values():
    if o['status']"'!='"'shipped': continue
    dt=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
    if not (start<=dt<end): continue
    cid=o['customer_id']
    if cid not in customers:
        attempts=0
        while True:
            st,b=request(f'/customers/{cid}',token=TOKEN)
            if st==200: break
            if st==404: raise RuntimeError(('unknown_customer',cid))
            attempts+=1
            if attempts>=8: raise RuntimeError(('customer',cid,st,b))
            time.sleep(min(2**attempts,20))
        customers[cid]=json.loads(b)
    c=customers[cid]
    amt=decimal.Decimal(o['amount_cents'])*(decimal.Decimal(100-c['discount_pct'])/decimal.Decimal(100))
    cents=int(amt.quantize(decimal.Decimal('1'),rounding=decimal.ROUND_HALF_UP))
    by_region[c['region']]+=cents
    qualifying.append((o,c,cents))
result={'total_cents':sum(by_region.values()),'order_count':len(qualifying),'duplicates_skipped':duplicate_listings,'by_region':by_region}
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print(json.dumps({'result':result,'pages':total_pages,'unique_listed':len(occurrences),'customer_count':len(customers),'offset_dates_utc_included':sum(1 for o,_,_ in qualifying if o['placed_at'][-6:] not in ('+00:00','-00:00') and not o['placed_at'].endswith('Z'))},indent=2))
